$script = @'
import io.github.diodeme.ji.session.model.*;
import java.time.*;
import java.util.*;
void reject(String name, Runnable r) { try { r.run(); System.out.println(name + "=ACCEPTED"); } catch (IllegalArgumentException | IllegalStateException e) { System.out.println(name + "=REJECTED:" + e.getMessage()); } }
var sid = new CanonicalSessionState.SessionId("session-1");
var rid = new CanonicalSessionState.RunId("run-1");
var tid = new CanonicalSessionState.TurnId("turn-1");
var modelDone = new CanonicalSessionState.Attempt(new CanonicalSessionState.AttemptId("model-1"), tid.value(), 1, CanonicalSessionState.AttemptStep.ASSISTANT, CanonicalSessionState.AttemptStatus.TERMINAL, Optional.of(CanonicalSessionState.AttemptOutcome.SUCCEEDED), 1, "assistant-1");
var toolId = new CanonicalSessionState.ToolExecutionId("tool-1");
var toolAttempt = new CanonicalSessionState.Attempt(new CanonicalSessionState.AttemptId("tool-attempt-1"), toolId.value(), 1, CanonicalSessionState.AttemptStep.TOOL, CanonicalSessionState.AttemptStatus.RUNNING, Optional.empty(), 0, "tool-result-1");
var preparedTool = new CanonicalSessionState.ToolExecution(toolId, sid, rid, tid, "call-1", "read", "tool-result-1", List.of(toolAttempt), CanonicalSessionState.ToolRetryContract.READ_ONLY, Optional.empty(), CanonicalSessionState.ToolStatus.PREPARED, Optional.empty(), 0);
var runningTool = new CanonicalSessionState.ToolExecution(toolId, sid, rid, tid, "call-1", "read", "tool-result-1", List.of(toolAttempt), CanonicalSessionState.ToolRetryContract.READ_ONLY, Optional.empty(), CanonicalSessionState.ToolStatus.RUNNING, Optional.empty(), 0);
reject("paused-running-tool-attempt", () -> new CanonicalSessionState.Turn(tid, rid, 1, CanonicalSessionState.TurnStatus.PAUSED, Optional.empty(), Optional.of(CanonicalSessionState.TurnPhase.WAITING_FOR_TOOLS), 0, List.of(modelDone), List.of(preparedTool), List.of()));
reject("terminal-running-tool", () -> new CanonicalSessionState.Turn(tid, rid, 1, CanonicalSessionState.TurnStatus.TERMINAL, Optional.of(CanonicalSessionState.TurnOutcome.COMPLETED), Optional.empty(), 0, List.of(modelDone), List.of(runningTool), List.of()));
var modelRunning = new CanonicalSessionState.Attempt(new CanonicalSessionState.AttemptId("model-live"), tid.value(), 1, CanonicalSessionState.AttemptStep.ASSISTANT, CanonicalSessionState.AttemptStatus.RUNNING, Optional.empty(), 0, "assistant-live");
var streaming = new CanonicalSessionState.Turn(tid, rid, 1, CanonicalSessionState.TurnStatus.MODEL_STREAMING, Optional.empty(), Optional.empty(), 0, List.of(modelRunning), List.of(), List.of());
reject("terminal-run-active-turn", () -> new CanonicalSessionState.Run(rid, sid, CanonicalSessionState.RunStatus.TERMINAL, Optional.of(CanonicalSessionState.RunOutcome.COMPLETED), Optional.empty(), 0, List.of(streaming), Instant.EPOCH, Optional.of(Instant.EPOCH.plusSeconds(1))));
var activeRun = new CanonicalSessionState.Run(rid, sid, CanonicalSessionState.RunStatus.RUNNING, Optional.empty(), Optional.empty(), 0, List.of(streaming), Instant.EPOCH, Optional.empty());
reject("trashed-session-active-run", () -> new CanonicalSessionState(sid, CanonicalSessionState.SessionStatus.TRASHED, Optional.empty(), 0, Optional.of(activeRun), List.of(), List.of()));
var hash = "0".repeat(64);
var cb = new CanonicalFacts.CommandWatermark(sid, 8);
var q = new CanonicalFacts.FollowUpQueue(3, List.of());
var log = new CanonicalFacts.AgentSessionLog(List.of(), 1);
var db = new CanonicalFacts.DeliveryWatermark(sid, 20, 1, 10, 4);
reject("hostcommit-snapshot-base-rollback", () -> new CanonicalFacts.HostCommit(Optional.empty(), cb, cb, q, q, log, List.of(), db, new CanonicalFacts.DeliveryWatermark(sid, 20, 2, 9, 4), 6));
var ev = new CanonicalFacts.DurableDelivery(sid, 21, 7, "session.updated", hash);
reject("hostcommit-eventseq-after-mismatch", () -> new CanonicalFacts.HostCommit(Optional.empty(), cb, cb, q, q, log, List.of(ev), db, new CanonicalFacts.DeliveryWatermark(sid, 22, 1, 10, 4), 6));
/exit
'@; $script | jshell --class-path 'ji-java/core/ji-session-api/build/classes/java/main'
